







SELECT gen_random_uuid(), s.id, v.stage_order, v.raw_label, v.raw_value, v.mapping_id, v.raw_value, v.measured_at
FROM samples s
JOIN (VALUES
  ('OK-BEFORE',1,'P-LOW',48.0,'00000000-0000-0000-0000-000000000050','2026-09-30 10:02:30+00'),
  ('OK-BEFORE',2,'P-MID',96.0,'00000000-0000-0000-0000-000000000051','2026-09-30 10:03:00+00'),
  ('OK-BEFORE',3,'P-HIGH',144.0,'00000000-0000-0000-0000-000000000052','2026-09-30 10:03:30+00'),
  ('OK-AFTER',1,'P-LOW',50.0,'00000000-0000-0000-0000-000000000050','2026-09-30 10:19:30+00'),
  ('OK-AFTER',2,'P-MID',100.0,'00000000-0000-0000-0000-000000000051','2026-09-30 10:20:00+00'),
  ('OK-AFTER',3,'P-HIGH',150.0,'00000000-0000-0000-0000-000000000052','2026-09-30 10:20:30+00'),
  ('LATE-BEFORE',1,'P-LOW',47.0,'00000000-0000-0000-0000-000000000050','2026-09-30 11:02:30+00'),
  ('LATE-BEFORE',2,'P-MID',95.0,'00000000-0000-0000-0000-000000000051','2026-09-30 11:03:00+00'),
  ('LATE-BEFORE',3,'P-HIGH',143.0,'00000000-0000-0000-0000-000000000052','2026-09-30 11:03:30+00'),
  ('LATE-AFTER',1,'P-LOW',49.0,'00000000-0000-0000-0000-000000000050','2026-09-30 11:19:30+00'),
  ('LATE-AFTER',2,'P-MID',99.0,'00000000-0000-0000-0000-000000000051','2026-09-30 11:20:00+00'),
  ('LATE-AFTER',3,'P-HIGH',149.0,'00000000-0000-0000-0000-000000000052','2026-09-30 11:20:30+00')
) AS v(code, stage_order, raw_label, raw_value, mapping_id, measured_at) ON v.code = s.sample_code
UNION ALL
SELECT gen_random_uuid(), s.id, x.stage_order, x.raw_label, x.raw_value, m.id, x.raw_value, x.measured_at
FROM samples s
JOIN LATERAL (VALUES
  (1,'P-LOW',49.0,'2026-09-30 10:02:30+00'),
  (2,'P-MID',98.0,'2026-09-30 10:03:00+00'),
  (3,'P-HIGH',148.0,'2026-09-30 10:03:30+00')
) x(stage_order, raw_label, raw_value, measured_at) ON true
LEFT JOIN pressure_calibration_mappings m ON m.instrument_label = x.raw_label AND m.active AND m.correction_level = 0
WHERE s.sample_code IN ('ALG-BEFORE','ALG-AFTER','LAYER-BEFORE','LAYER-AFTER','NO-BEFORE-AFTER');

SELECT gen_random_uuid(), s.id, g.bin_um,
  CASE
    WHEN s.sample_type = 'BEFORE' THEN greatest(0, 10.2 - (g.n - 1) * 0.55 + CASE WHEN s.layer = 'BOTTOM' THEN 0.8 ELSE 0 END)
    ELSE greatest(0, 6.4 - (g.n - 1) * 0.32)
  END
FROM samples s
CROSS JOIN LATERAL (VALUES (1,0.1),(2,0.2),(3,0.5),(4,1.0),(5,2.0),(6,5.0),(7,10.0),(8,20.0),(9,50.0),(10,100.0)) AS g(n, bin_um);
